    {selected && <div className="admin-modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && closeDetails()}><section className="admin-modal admin-modal-small"><div className="admin-modal-head"><div><span>Customer story</span><h2>{selected.name}</h2></div><button onClick={closeDetails} aria-label="Close"><X size={19} /></button></div><div className="customer-detail"><span>{selected.email}</span><span>{selected.phone || 'No phone on file'}</span><span>{selected.orders} orders · {currency(selected.spent)} spent</span></div><h3 className="customer-orders-heading">Saved addresses · {detail.data?.addresses.length ?? '…'}</h3>{detail.data?.addresses.length ? <div className="customer-address-list">{detail.data.addresses.map((address) => <article className="customer-address-card" key={address._id}><div><b>{address.label || 'Address'}</b>{address.isDefault && <span className="customer-default-address">Default</span>}</div><p>{address.fullName} · {address.phone}</p><p>{[address.line1, address.line2, address.city, address.state, address.postalCode, address.country].filter(Boolean).join(', ')}</p></article>)}</div> : <div className="customer-address-empty">{detail.isLoading ? 'Loading saved addresses…' : 'No saved addresses on file.'}</div>}<h3 className="customer-orders-heading">Order history · {detail.data?.pagination.total ?? '…'}</h3><div className="customer-order-history">{detail.isLoading ? <div className="table-loading">Gathering order history…</div> : detail.isError ? <div className="table-loading">Couldn’t load order history. <button className="admin-text-button" onClick={() => void detail.refetch()}>Try again</button></div> : detail.data?.orders.length ? detail.data.orders.map((order) => <div className="customer-order-line" key={order._id}><span><b>{order.orderNumber}</b><small>{new Date(order.createdAt).toLocaleDateString('en-IN')} · {order.status}</small></span><span>{currency(order.total)}</span></div>) : <div className="table-loading">No orders have been placed yet.</div>}</div><AdminPagination page={detailPage} pages={detail.data?.pagination.pages || 1} setPage={setDetailPage} /></section></div>}</>
