const optionalCouponMoney = z.union([z.string(), z.number()]).optional().transform((value) => value === undefined || value === '' ? undefined : Number(value)).pipe(z.number().min(0).optional())
const optionalCouponPositive = z.union([z.string(), z.number()]).optional().transform((value) => value === undefined || value === '' ? undefined : Number(value)).pipe(z.number().positive().optional())
const optionalCouponPositiveInt = z.union([z.string(), z.number()]).optional().transform((value) => value === undefined || value === '' ? undefined : Number(value)).pipe(z.number().int().positive().optional())
const couponFormSchema = z.object({ code: z.string().trim().min(3).transform((v) => v.toUpperCase()), type: z.enum(['percent', 'fixed']), value: z.coerce.number().positive(), minSubtotal: optionalCouponMoney, maxDiscount: optionalCouponPositive, usageLimit: optionalCouponPositiveInt, expiresAt: z.string().optional() }).superRefine((coupon, context) => { if (coupon.type === 'percent' && coupon.value > 100) context.addIssue({ code: 'custom', path: ['value'], message: 'Percentage discounts cannot exceed 100%.' }); if (coupon.expiresAt && Number.isNaN(Date.parse(coupon.expiresAt))) context.addIssue({ code: 'custom', path: ['expiresAt'], message: 'Choose a valid expiry date.' }) })
const bannerFormSchema = z.object({ title: z.string().trim().min(2), subtitle: z.string().optional(), image: z.string().url(), href: z.string().optional(), placement: z.enum(['hero', 'promo', 'collection']), sortOrder: z.coerce.number().default(0) })
function Promotions() {
  type CouponRecord = { _id: string; code: string; type: 'percent' | 'fixed'; value: number; minSubtotal: number; maxDiscount?: number; usedCount: number; usageLimit?: number; expiresAt?: string; isActive: boolean }
  type BannerRecord = { _id: string; title: string; subtitle?: string; image: string; href?: string; placement: 'hero' | 'promo' | 'collection'; sortOrder: number; isActive: boolean }
  const [tab, setTab] = useState<'coupons' | 'banners'>('coupons'), [showCoupon, setShowCoupon] = useState(false), [showBanner, setShowBanner] = useState(false), [editingCoupon, setEditingCoupon] = useState<CouponRecord | null>(null), [editingBanner, setEditingBanner] = useState<BannerRecord | null>(null), client = useQueryClient(), toast = useToast()
  const coupons = useQuery({ queryKey: ['admin-coupons'], queryFn: async () => (await api.get('/admin/coupons')).data.coupons as CouponRecord[] })
  const banners = useQuery({ queryKey: ['admin-banners'], queryFn: async () => (await api.get('/admin/banners')).data.banners as BannerRecord[] })
  const couponDefaults = { code: '', type: 'percent' as const, value: 10, minSubtotal: 0, maxDiscount: '', usageLimit: '', expiresAt: '' }
  const bannerDefaults = { title: '', subtitle: '', image: '', href: '/shop', placement: 'promo' as const, sortOrder: 0 }
  const cf = useForm({ resolver: zodResolver(couponFormSchema), defaultValues: couponDefaults })
  const bf = useForm({ resolver: zodResolver(bannerFormSchema), defaultValues: bannerDefaults })
  const closeCoupon = () => { setShowCoupon(false); setEditingCoupon(null); cf.reset(couponDefaults) }
  const closeBanner = () => { setShowBanner(false); setEditingBanner(null); bf.reset(bannerDefaults) }
  const openCoupon = (coupon?: CouponRecord) => { setEditingCoupon(coupon || null); cf.reset(coupon ? { code: coupon.code, type: coupon.type, value: coupon.value, minSubtotal: coupon.minSubtotal || 0, maxDiscount: coupon.maxDiscount ?? '', usageLimit: coupon.usageLimit ?? '', expiresAt: coupon.expiresAt?.slice(0, 10) || '' } : couponDefaults); setShowCoupon(true) }
  const openBanner = (banner?: BannerRecord) => { setEditingBanner(banner || null); bf.reset(banner ? { title: banner.title, subtitle: banner.subtitle || '', image: banner.image, href: banner.href || '', placement: banner.placement, sortOrder: banner.sortOrder || 0 } : bannerDefaults); setShowBanner(true) }
  const refreshPromotions = async () => { await Promise.all([client.invalidateQueries({ queryKey: ['admin-coupons'] }), client.invalidateQueries({ queryKey: ['admin-banners'] }), client.invalidateQueries({ queryKey: ['banners'] })]) }
  const saveCoupon = async (values: z.infer<typeof couponFormSchema>) => {
    const expiresAt = values.expiresAt ? new Date(`${values.expiresAt}T23:59:59.999`) : undefined
    const payload = { code: values.code, type: values.type, value: values.value, minSubtotal: values.minSubtotal, ...(values.maxDiscount !== undefined ? { maxDiscount: values.maxDiscount } : {}), ...(values.usageLimit !== undefined ? { usageLimit: values.usageLimit } : {}), ...(expiresAt ? { expiresAt } : {}) }
    try {
      if (editingCoupon) await api.patch(`/admin/coupons/${editingCoupon._id}`, { type: values.type, value: values.value, minSubtotal: values.minSubtotal, maxDiscount: values.maxDiscount ?? null, usageLimit: values.usageLimit ?? null, expiresAt: expiresAt || null })
      else await api.post('/admin/coupons', payload)
      await refreshPromotions(); closeCoupon(); toast(editingCoupon ? 'Coupon changes saved.' : 'Your coupon is ready.')
    } catch (e) { toast(messageOf(e), 'error') }
  }
  const saveBanner = async (values: z.infer<typeof bannerFormSchema>) => {
    try {
      if (editingBanner) await api.patch(`/admin/banners/${editingBanner._id}`, values)
      else await api.post('/admin/banners', values)
      await refreshPromotions(); closeBanner(); toast(editingBanner ? 'Banner changes saved.' : 'Banner added to your storefront.')
    } catch (e) { toast(messageOf(e), 'error') }
  }
  const toggleActive = async (type: 'coupon' | 'banner', id: string, isActive: boolean) => {
    try { await api.patch(`/admin/${type === 'coupon' ? 'coupons' : 'banners'}/${id}`, { isActive: !isActive }); await refreshPromotions(); toast(isActive ? 'Promotion paused.' : 'Promotion activated.') }
    catch (e) { toast(messageOf(e), 'error') }
  }
  const remove = async (type: 'coupon' | 'banner', id: string, name: string) => {
    if (!window.confirm(`Remove “${name}”? This cannot be undone.`)) return
    try { await api.delete(`/admin/${type === 'coupon' ? 'coupons' : 'banners'}/${id}`); await refreshPromotions(); toast('Removed.') }
    catch (e) { toast(messageOf(e), 'error') }
  }
  return <><PageHead eyebrow="A little something extra" title="Promotions" action={<button className="admin-primary" onClick={() => tab === 'coupons' ? openCoupon() : openBanner()}><Plus size={16} /> {tab === 'coupons' ? 'Create a coupon' : 'Add a banner'}</button>} /><div className="admin-filter-tabs promotion-tabs"><button className={tab === 'coupons' ? 'active' : ''} onClick={() => setTab('coupons')}><Tag size={14} /> Coupons</button><button className={tab === 'banners' ? 'active' : ''} onClick={() => setTab('banners')}><Activity size={14} /> Storefront banners</button></div>
    {tab === 'coupons' ? <section className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Code</th><th>Offer</th><th>Used</th><th>Expires</th><th>Status</th><th>Actions</th></tr></thead><tbody>{coupons.data?.map((c) => <tr key={c._id}><td><b className="coupon-code">{c.code}</b></td><td>{c.type === 'percent' ? `${c.value}% off` : `${currency(c.value)} off`}</td><td>{c.usedCount}{c.usageLimit ? ` / ${c.usageLimit}` : ' times'}</td><td>{c.expiresAt ? new Date(c.expiresAt).toLocaleDateString('en-IN') : 'No expiry'}</td><td><span className={`published-pill ${c.isActive ? '' : 'archived'}`}><i />{c.isActive ? 'Active' : 'Paused'}</span></td><td><div className="table-actions"><button onClick={() => openCoupon(c)}><Pencil size={13} /> Edit</button><button onClick={() => void toggleActive('coupon', c._id, c.isActive)} aria-label={c.isActive ? 'Pause coupon' : 'Activate coupon'}>{c.isActive ? <Pause size={13} /> : <Play size={13} />}{c.isActive ? 'Pause' : 'Activate'}</button><button onClick={() => void remove('coupon', c._id, c.code)} aria-label="Delete coupon"><Trash2 size={14} /></button></div></td></tr>)}</tbody></table>{coupons.isLoading && <div className="table-loading">Gathering your coupons…</div>}{coupons.isError && <div className="table-loading">Couldn’t load coupons. <button className="admin-text-button" onClick={() => void coupons.refetch()}>Try again</button></div>}{coupons.data?.length === 0 && <div className="table-loading">No coupons yet. A little surprise goes a long way.</div>}</section> : <div className="promo-banner-grid">{banners.data?.map((b) => <article className={`promo-banner-card ${!b.isActive ? 'promo-banner-inactive' : ''}`} key={b._id}><img src={b.image} alt="" /><div><span>{b.placement} · {b.isActive ? 'Live' : 'Paused'}</span><h3>{b.title}</h3><p>{b.subtitle}</p><div className="promo-banner-controls"><button onClick={() => openBanner(b)}><Pencil size={13} /> Edit</button><button onClick={() => void toggleActive('banner', b._id, b.isActive)}>{b.isActive ? <Pause size={13} /> : <Play size={13} />}{b.isActive ? 'Pause' : 'Activate'}</button><button onClick={() => void remove('banner', b._id, b.title)}><Trash2 size={13} /> Remove</button></div></div></article>)}{banners.data && !banners.data.length && <div className="table-loading">No storefront banners yet.</div>}{banners.isError && <div className="table-loading">Couldn’t load banners. <button className="admin-text-button" onClick={() => void banners.refetch()}>Try again</button></div>}</div>}
    {showCoupon && <div className="admin-modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && closeCoupon()}><section className="admin-modal admin-modal-small"><ModalHead title={editingCoupon ? `Edit ${editingCoupon.code}` : 'Make a little offer'} close={closeCoupon} /><form className="admin-product-form" onSubmit={cf.handleSubmit(saveCoupon)}><label className="field"><span>Coupon code</span><input {...cf.register('code')} placeholder="GOODTHINGS" readOnly={Boolean(editingCoupon)} />{cf.formState.errors.code?.message && <small className="field-error">{cf.formState.errors.code.message}</small>}</label><div className="form-grid admin-two"><label className="field"><span>Offer type</span><select {...cf.register('type')}><option value="percent">Percentage off</option><option value="fixed">Fixed amount off</option></select></label><label className="field"><span>Amount</span><input type="number" min="0.01" max={cf.watch('type') === 'percent' ? 100 : undefined} step="0.01" {...cf.register('value')} />{cf.formState.errors.value?.message && <small className="field-error">{cf.formState.errors.value.message}</small>}</label><label className="field"><span>Minimum basket ({storeCurrencyCode()})</span><input type="number" min="0" step="0.01" {...cf.register('minSubtotal')} />{cf.formState.errors.minSubtotal?.message && <small className="field-error">{cf.formState.errors.minSubtotal.message}</small>}</label><label className="field"><span>Maximum discount ({storeCurrencyCode()})</span><input type="number" min="0.01" step="0.01" {...cf.register('maxDiscount')} placeholder="No limit" />{cf.formState.errors.maxDiscount?.message && <small className="field-error">{cf.formState.errors.maxDiscount.message}</small>}</label><label className="field"><span>Maximum uses</span><input type="number" min="1" step="1" {...cf.register('usageLimit')} placeholder="No limit" />{cf.formState.errors.usageLimit?.message && <small className="field-error">{cf.formState.errors.usageLimit.message}</small>}</label><label className="field"><span>Expiry date</span><input type="date" {...cf.register('expiresAt')} />{cf.formState.errors.expiresAt?.message && <small className="field-error">{cf.formState.errors.expiresAt.message}</small>}</label></div><div className="admin-modal-actions"><button type="button" className="admin-secondary" onClick={closeCoupon}>Cancel</button><button className="admin-primary">{editingCoupon ? 'Save changes' : 'Create coupon'} <ArrowRight size={14} /></button></div></form></section></div>}
    {showBanner && <div className="admin-modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && closeBanner()}><section className="admin-modal admin-modal-small"><ModalHead title={editingBanner ? 'Edit a storefront banner' : 'Add a storefront banner'} close={closeBanner} /><form className="admin-product-form" onSubmit={bf.handleSubmit(saveBanner)}><label className="field"><span>Headline</span><input {...bf.register('title')} placeholder="A little more considered" /></label><label className="field"><span>Short note</span><input {...bf.register('subtitle')} /></label><label className="field"><span>Image URL</span><input {...bf.register('image')} placeholder="https://…" /></label><div className="form-grid admin-two"><label className="field"><span>Placement</span><select {...bf.register('placement')}><option value="hero">Homepage hero</option><option value="promo">Promotion</option><option value="collection">Collection feature</option></select></label><label className="field"><span>Sort order</span><input type="number" {...bf.register('sortOrder')} /></label></div><label className="field"><span>Link</span><input {...bf.register('href')} placeholder="/shop" /></label><div className="admin-modal-actions"><button type="button" className="admin-secondary" onClick={closeBanner}>Cancel</button><button className="admin-primary">{editingBanner ? 'Save changes' : 'Add banner'} <ArrowRight size={14} /></button></div></form></section></div>}</>
}
function ModalHead({ title, close }: { title: string; close: () => void }) { return <div className="admin-modal-head"><div><span>Promotions</span><h2>{title}</h2></div><button onClick={close} aria-label="Close"><X size={19} /></button></div> }

function Analytics() {
  const query = useOverview(), d = query.data, max = Math.max(1, ...(d?.categoryPerformance || []).map((c) => c.revenue))
  return <><PageHead eyebrow="A little look at the bigger picture" title="Analytics" /><div className="analytics-note"><Activity size={16} /> Numbers update as orders come in. All values are in Indian rupees.</div><div className="metric-grid"><article className="metric-card"><div className="metric-icon sage"><CircleDollarSign size={17} /></div><span>Revenue to date</span><strong>{currency(d?.metrics.revenue || 0)}</strong><small>Orders not cancelled or refunded</small></article><article className="metric-card"><div className="metric-icon sand"><ShoppingBag size={17} /></div><span>Orders placed</span><strong>{d?.metrics.totalOrders || 0}</strong><small>All time</small></article><article className="metric-card"><div className="metric-icon peach"><Package size={17} /></div><span>Active pieces</span><strong>{d?.metrics.totalProducts || 0}</strong><small>{d?.metrics.lowStockCount || 0} have 5 or fewer left</small></article><article className="metric-card"><div className="metric-icon lavender"><Users size={17} /></div><span>Community</span><strong>{d?.metrics.totalCustomers || 0}</strong><small>Customer accounts</small></article></div><div className="admin-overview-grid analytics-grid"><section className="admin-panel revenue-panel"><div className="panel-head"><div><span>LAST 30 DAYS</span><h2>Revenue by day</h2></div></div><div className="revenue-chart large-chart">{d?.dailySales.slice(-30).map((point) => <div className="revenue-bar-column" key={point._id} title={`${point._id}: ${currency(point.revenue)}`}><div className="revenue-bar" style={{ height: `${Math.max(5, point.revenue / Math.max(1, ...d.dailySales.map((x) => x.revenue)) * 100)}%` }} /><small>{new Date(point._id).toLocaleDateString('en-IN', { day: 'numeric' })}</small></div>) || <div className="chart-empty">Your sales story will start here.</div>}</div><div className="chart-footer"><span>30 DAY TOTAL</span><b>{currency(d?.dailySales.reduce((s, p) => s + p.revenue, 0) || 0)}</b></div></section><section className="admin-panel category-performance"><div className="panel-head"><div><span>WHERE THINGS ARE GOING</span><h2>By collection</h2></div></div>{d?.categoryPerformance.map((category) => <div className="performance-row" key={category._id}><div><b>{category._id}</b><span>{category.units} pieces</span></div><strong>{currency(category.revenue)}</strong><div className="performance-track"><i style={{ width: `${Math.max(4, category.revenue / max * 100)}%` }} /></div></div>) || <p className="admin-empty">Collection performance will show once orders start coming in.</p>}</section></div><section className="admin-panel report-products"><div className="panel-head"><div><span>THE PEOPLE HAVE SPOKEN</span><h2>Best-selling pieces</h2></div></div>{d?.bestSellers.map((product, i) => <div className="bestseller-row" key={product._id}><span className="bestseller-rank">0{i + 1}</span><img src={imageUrl(product.images?.[0])} alt="" /><span><b>{product.name}</b><small>{typeof product.category === 'string' ? '' : product.category?.name}</small></span><strong>{product.soldCount || 0} sold</strong></div>)}</section></>
}
function AdminPagination({ page, pages, setPage }: { page: number; pages: number; setPage: (page: number) => void }) { if (pages <= 1) return null; return <div className="admin-pagination"><button disabled={page <= 1} onClick={() => setPage(page - 1)}><ChevronLeft size={15} /> Previous</button><span>Page {page} of {pages}</span><button disabled={page >= pages} onClick={() => setPage(page + 1)}>Next <ChevronRight size={15} /></button></div> }
